import * as THREE from 'three/webgpu';
import { texture, uv, vec4, color, mix, step } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-thumbnail';
  group.position.set(2.5, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;
  const captionHeight = 0.22;

  const geometry = new THREE.PlaneGeometry(width, height);
  const map = ctx.textureLoader.load('/prism-mock/home/nodes/cta-hero-isolated.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  const imgTex = texture(map, uv());

  const captionColor = color(0x16161d);
  const captionThreshold = captionHeight / height;
  const captionMask = step(uv().y, captionThreshold);

  const finalColor = mix(imgTex.rgb, captionColor, captionMask);
  material.colorNode = vec4(finalColor, 1.0);

  const cardMesh = new THREE.Mesh(geometry, material);
  cardMesh.name = 'thumbnail-plane';
  group.add(cardMesh);

  // accent edge (focus indicator), hidden by default
  const edgeGeo = new THREE.PlaneGeometry(width + 0.03, height + 0.03);
  const edgeMat = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0,
    color: new THREE.Color(0xff2a38),
  });
  const edgeMesh = new THREE.Mesh(edgeGeo, edgeMat);
  edgeMesh.position.z = -0.001;
  edgeMesh.name = 'accent-edge';
  group.add(edgeMesh);

  const basePosition = group.position.clone();
  let hoverTween = null;
  let pressTween = null;

  function onHoverIn() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: basePosition.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsap.to(edgeMat, { opacity: 0.6, duration: 0.3 });
  }

  function onHoverOut() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: basePosition.y,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsap.to(edgeMat, { opacity: 0, duration: 0.3 });
  }

  function onClick() {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'back.out' });

    if (group.userData.emit) {
      group.userData.emit('hub-journal.select', { nodeId: 'hub-journal-card-thumbnail' });
    }
  }

  group.userData.handlers = {
    onHoverIn,
    onHoverOut,
    onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    geometry.dispose();
    material.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    if (map) map.dispose();
  };

  return group;
}
